'use strict';

const { items, localDay, addDays, remaining, availability } = Ledger;
const key = 'shared-cupboard-ledger-v1';
const names = { overview: 'Overview', loans: 'Current loans', reservations: 'Reservations', availability: 'Availability' };
const fullDate = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
const todayDate = new Intl.DateTimeFormat(undefined, { weekday: 'long', day: 'numeric', month: 'long' });
const view = document.querySelector('#view');
const dialog = document.querySelector('#dialog');
const form = document.querySelector('#record-form');
const storageAlert = document.querySelector('#storage-alert');
let state;
let page;
let today = localDay();
let range = { start: today, end: addDays(today, 7) };
let editing;
let toastTimer;

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, char =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
}

function date(day) {
  return fullDate.format(new Date(day + 'T12:00:00'));
}

function icon(name) {
  return `<canvas class="icon" data-icon="${name}" width="20" height="20" aria-hidden="true"></canvas>`;
}

function itemLabel(id) {
  const item = items.find(entry => entry.id === id);
  return item.capacity === 1 ? `${item.name} · ${item.id}` : item.name;
}

function load() {
  const raw = localStorage.getItem(key);
  if (raw === null) return { loans: [], reservations: [] };
  const stored = JSON.parse(raw);
  if (!Array.isArray(stored.loans) || !Array.isArray(stored.reservations)) {
    throw new Error('The saved ledger could not be read.');
  }
  return stored;
}

function refreshState() {
  try {
    state = load();
    storageAlert.hidden = true;
  } catch {
    state = null;
    storageAlert.textContent = 'The saved ledger could not be opened. Use the browser profile and file location normally used for the cupboard.';
    storageAlert.hidden = false;
  }
}

function currentLoans() {
  return state.loans.filter(loan => remaining(loan) > 0)
    .sort((a, b) => a.end.localeCompare(b.end) || a.start.localeCompare(b.start));
}

function activeReservations() {
  return state.reservations.filter(booking => booking.end >= today)
    .sort((a, b) => a.start.localeCompare(b.start));
}

function badge(text, tone) {
  return `<span class="badge ${tone}"><span></span>${text}</span>`;
}

function loanStatus(loan) {
  if (loan.end < today) return badge('Overdue', 'alarm');
  if (loan.end === today) return badge('Due today', 'warm');
  return badge('On loan', 'neutral');
}

function button(label, action, style = '', symbol = '') {
  return `<button type="button" class="button ${style}" data-action="${action}">${symbol ? icon(symbol) : ''}${label}</button>`;
}

function empty(symbol, title, message) {
  return `<div class="empty"><span class="empty-icon">${icon(symbol)}</span><div><strong>${title}</strong><p>${message}</p></div></div>`;
}

function heading(title, subtitle, actions = '') {
  return `<header class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>
    ${actions ? `<div class="actions">${actions}</div>` : ''}</header>`;
}

function inventoryCard(item) {
  const { free, peak } = availability(state, item.id, today, today, today);
  const tagged = item.capacity === 1;
  const status = tagged
    ? (free ? 'Available' : peak.blockers.some(span => span.kind === 'loan') ? 'On loan' : 'Reserved')
    : `${free} of ${item.capacity} available`;
  return `<article class="inventory-card">
    <div class="inventory-art ${item.art}"><canvas data-art="${item.art}" width="64" height="60" aria-hidden="true"></canvas></div>
    <div class="inventory-label"><span class="item-tag">${tagged ? item.id : 'By quantity'}</span><h3>${item.name}</h3></div>
    ${badge(status, free ? 'good' : 'warm')}
  </article>`;
}

function loanRows(loans, print = false) {
  return loans.map(loan => `<tr>
    <td data-label="Item"><strong>${itemLabel(loan.item)}</strong></td>
    <td data-label="Household">${escapeHtml(loan.household)}</td>
    <td data-label="Out">${remaining(loan)}${!print && loan.returned ? ` <small>of ${loan.quantity}</small>` : ''}</td>
    <td data-label="Checked out">${date(loan.start)}</td>
    <td data-label="Expected back">${date(loan.end)}</td>
    <td data-label="Status">${print ? (loan.end < today ? 'OVERDUE' : loan.end === today ? 'Due today' : 'On loan') : loanStatus(loan)}</td>
    ${print ? '' : `<td data-label="Action"><button type="button" class="button compact" data-action="return" data-id="${loan.id}" aria-label="Record return for ${escapeHtml(loan.household)} · ${itemLabel(loan.item)}">Return</button></td>`}
  </tr>`).join('');
}

function loanTable(loans, print = false) {
  return `<table aria-label="Current loans"><thead><tr><th scope="col">Item</th><th scope="col">Household</th><th scope="col">Out</th><th scope="col">Checked out</th><th scope="col">Expected back</th><th scope="col">Status</th>${print ? '' : '<th scope="col">Action</th>'}</tr></thead>
    <tbody>${loanRows(loans, print)}</tbody></table>`;
}

function overview() {
  const loans = currentLoans();
  const bookings = activeReservations();
  return `<section class="hero">
    <div class="hero-copy"><h1>Shared Cupboard</h1>
      <p>Check items out, record returns, and set things aside for your neighbors.</p>
      <div class="actions">${button('New checkout', 'checkout', 'primary', 'plus')}${button('New reservation', 'reserve', 'on-dark', 'calendar')}</div>
    </div>
    <div class="hero-art" aria-hidden="true"><canvas data-art="shelf" width="364" height="220"></canvas></div>
  </section>
  <section class="inventory"><div class="section-head"><div><h2>Today’s inventory</h2><p>Availability for pickup today</p></div>
    <a class="text-link" href="#availability">Check a date range ${icon('arrow')}</a></div>
    <div class="inventory-grid">${items.map(inventoryCard).join('')}</div>
  </section>
  <div class="dashboard-grid">
    <section class="panel"><div class="panel-head"><h2>Current loans <span class="count">${loans.length}</span></h2>${button('Print sheet', 'print', 'compact', 'print')}</div>
      ${loans.length ? `<ul class="mini-list">${loans.slice(0, 4).map(loan =>
        `<li><div><strong>${itemLabel(loan.item)}${loan.item === 'cords' ? ` × ${remaining(loan)}` : ''}</strong><small>${escapeHtml(loan.household)} · Due ${date(loan.end)}</small></div>${loanStatus(loan)}</li>`).join('')}</ul>
        <a class="text-link panel-link" href="#loans">Manage current loans ${icon('arrow')}</a>`
      : empty('loan', 'Nothing on loan', 'Checkouts will appear here until they are returned.')}</section>
    <section class="panel"><div class="panel-head"><h2>Reservations <span class="count">${bookings.length}</span></h2>
      <a class="text-link" href="#reservations">View all ${icon('arrow')}</a></div>
      ${bookings.length ? `<ul class="mini-list">${bookings.slice(0, 3).map(booking =>
        `<li><div><strong>${itemLabel(booking.item)}${booking.item === 'cords' ? ` × ${booking.quantity}` : ''}</strong><small>${escapeHtml(booking.household)} · ${date(booking.start)} – ${date(booking.end)}</small></div></li>`).join('')}</ul>`
      : empty('calendar', 'No reservations yet', 'Upcoming reservations will appear here.')}</section>
  </div>`;
}

function loansPage() {
  const loans = currentLoans();
  return heading('Current loans', 'Record returns and follow up on overdue items.',
    button('Print sheet', 'print', '', 'print') + button('New checkout', 'checkout', 'primary', 'plus')) +
    `<section class="panel table-panel">${loans.length ? loanTable(loans) :
      empty('loan', 'Nothing on loan', 'Use New checkout to record a household borrowing an item.')}</section>`;
}

function reservationsPage() {
  const bookings = activeReservations();
  return heading('Reservations', 'Manage upcoming bookings and check items out at pickup.',
    button('New reservation', 'reserve', 'primary', 'plus')) +
    `<section class="panel table-panel">${bookings.length ? `<table aria-label="Reservations"><thead><tr><th scope="col">Item</th><th scope="col">Household</th>
      <th scope="col">Quantity</th><th scope="col">From</th><th scope="col">Through</th><th scope="col">Action</th></tr></thead><tbody>
      ${bookings.map(booking => `<tr><td data-label="Item"><strong>${itemLabel(booking.item)}</strong></td><td data-label="Household">${escapeHtml(booking.household)}</td>
      <td data-label="Quantity">${booking.quantity}</td><td data-label="From">${date(booking.start)}</td><td data-label="Through">${date(booking.end)}</td>
      <td data-label="Action"><div class="row-actions">${booking.start <= today ? `<button type="button" class="button compact" data-action="pickup" data-id="${booking.id}">Check out</button>` : ''}
      <button type="button" class="button compact" data-action="cancel-booking" data-id="${booking.id}" aria-label="Cancel reservation for ${escapeHtml(booking.household)} · ${itemLabel(booking.item)}">Cancel</button></div></td></tr>`).join('')}
      </tbody></table>` : empty('calendar', 'No reservations yet', 'Use New reservation to hold an item for a date range.')}</section>`;
}

function spanText(span) {
  const household = escapeHtml(span.household);
  if (span.kind === 'reservation') {
    return `${household} · ${span.quantity} reserved · ${date(span.start)} – ${date(span.end)}`;
  }
  return `${household} · ${span.quantity} on loan · ${span.end === null
    ? `overdue · due ${date(span.due)} · held until returned`
    : `due ${date(span.due)}`}`;
}

function availabilityResults() {
  return `<div class="section-head"><div><h2>Available for the full range</h2><p>${date(range.start)} – ${date(range.end)}</p></div></div>
    <div class="availability-list">${items.map(item => {
      const result = availability(state, item.id, range.start, range.end, today);
      return `<article class="panel availability-item">
        <div class="availability-title"><div class="inventory-art ${item.art}"><canvas data-art="${item.art}" width="64" height="60" aria-hidden="true"></canvas></div>
        <div><span class="item-tag">${item.capacity === 1 ? item.id : 'By quantity'}</span><h3>${item.name}</h3></div></div>
        ${badge(item.capacity === 1 ? (result.free ? 'Available' : 'Unavailable') :
          `${result.free} of ${item.capacity} available`, result.free ? 'good' : 'warm')}
        ${result.free && range.start > today ? `<button type="button" class="button compact" data-action="reserve-range" data-item="${item.id}">Reserve</button>` : ''}
        ${result.spans.length ? `<details><summary>View overlapping commitments</summary><ul>${result.spans.map(span => `<li>${spanText(span)}</li>`).join('')}</ul></details>` : ''}
      </article>`;
    }).join('')}</div>`;
}

function availabilityPage() {
  return heading('Availability', 'Find out what a household can borrow across a date range.',
    button('New reservation', 'reserve', 'primary', 'plus')) +
    `<form id="range-form" class="panel range-form">
      <label>From<input type="date" name="start" value="${range.start}" min="${today}" max="9999-12-31" required></label>
      <label>Through<input type="date" name="end" value="${range.end}" min="${range.start}" max="9999-12-31" required></label>
      <button type="submit" class="button dark">${icon('search')}Check availability</button>
      <p>Both dates count. Overdue items are held until returned.</p>
    </form>
    <section id="range-results" class="range-results" aria-live="polite">${availabilityResults()}</section>`;
}

function renderPrint() {
  const loans = state ? currentLoans() : [];
  document.querySelector('#print-sheet').innerHTML = `<h1>Shared Cupboard · Current loans</h1>
    <p>As of ${date(today)}</p>${state ? (loans.length ? loanTable(loans, true) : '<p>No items are currently on loan.</p>') : '<p>The saved ledger could not be opened.</p>'}`;
}

function render() {
  today = localDay();
  if (range.start < today) {
    range = { start: today, end: range.end < today ? addDays(today, 7) : range.end };
  }
  const target = location.hash.slice(1);
  const requested = Object.hasOwn(names, target) ? target : (target === 'main' && page ? page : 'overview');
  const changed = page && page !== requested;
  page = requested;
  document.querySelector('#section-name').textContent = names[page];
  document.querySelector('#today').innerHTML = icon('calendar') + todayDate.format(new Date());
  for (const link of document.querySelectorAll('nav a')) {
    if (link.hash === '#' + page) link.setAttribute('aria-current', 'page');
    else link.removeAttribute('aria-current');
  }
  view.innerHTML = state ? { overview, loans: loansPage, reservations: reservationsPage, availability: availabilityPage }[page]() : '';
  renderPrint();
  paintArt(document);
  if (changed) {
    document.querySelector('#main').focus({ preventScroll: true });
    window.scrollTo(0, 0);
  }
}

function showToast(message) {
  const toast = document.querySelector('#toast');
  toast.textContent = message;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { toast.textContent = ''; }, 4200);
}

function dateField(label, name, value, limits = '') {
  return `<label>${label}<input type="date" name="${name}" value="${value}" ${limits} required></label>`;
}

function openEditor(mode, record, item) {
  today = localDay();
  editing = { mode, id: record?.id };
  const tomorrow = addDays(today, 1);
  let title;
  let message;
  let fields = '';
  let submit;
  if (mode === 'checkout' || mode === 'reserve') {
    const booking = mode === 'reserve';
    const start = booking ? (item ? range.start : tomorrow) : today;
    const end = booking && item ? range.end : start;
    title = booking ? 'New reservation' : 'New checkout';
    message = booking ? 'Both dates are included in the reservation.' : 'Use a short household label, such as 4B.';
    submit = booking ? 'Save reservation' : 'Save checkout';
    fields = `<label>Household label<input name="household" maxlength="24" placeholder="e.g. 4B" required autofocus></label>
      <div class="field-row"><label>Item<select name="item">${items.map(entry =>
        `<option value="${entry.id}" ${item === entry.id ? 'selected' : ''}>${itemLabel(entry.id)}</option>`).join('')}</select></label>
      <label id="quantity-field" hidden>Quantity<input type="number" name="quantity" value="1" min="1" max="3" step="1" required></label></div>
      <div class="field-row">${dateField(booking ? 'From' : 'Checkout date', 'start', start, booking ? `min="${tomorrow}" max="9999-12-31"` : `max="${today}"`)}
      ${dateField(booking ? 'Through' : 'Expected return date', 'end', end, `min="${start}" max="9999-12-31"`)}</div>`;
  } else {
    const summary = `${itemLabel(record.item)} · ${escapeHtml(record.household)}`;
    if (mode === 'return') {
      const out = remaining(record);
      title = 'Record return';
      message = `${summary} · ${out} currently out`;
      submit = 'Save return';
      if (record.item === 'cords') {
        fields = `<label>Quantity returned<input type="number" name="quantity" min="1" max="${out}" value="${out}" step="1" required autofocus></label>`;
      }
    } else if (mode === 'pickup') {
      title = 'Check out reservation';
      message = `${summary} · Quantity ${record.quantity} · Expected back ${date(record.end)}`;
      submit = 'Confirm checkout';
    } else {
      title = 'Cancel reservation';
      message = `${summary} · ${date(record.start)} – ${date(record.end)}`;
      submit = 'Cancel reservation';
    }
  }

  document.querySelector('#dialog-content').innerHTML = `
    <header class="dialog-head"><h2 id="dialog-title">${title}</h2>
      <button type="button" class="icon-button" data-action="close-dialog" aria-label="Close">${icon('close')}</button></header>
    <p class="dialog-message">${message}</p>
    <div class="fields">${fields}</div>
    <div id="form-error" class="error" role="alert" tabindex="-1" hidden></div>
    <footer class="dialog-actions">${button(mode === 'cancel-booking' ? 'Keep reservation' : 'Cancel', 'close-dialog')}
      <button type="submit" class="button primary">${submit}</button></footer>`;
  syncQuantity();
  dialog.showModal();
  paintArt(dialog);
}

function syncQuantity() {
  const field = form.querySelector('#quantity-field');
  if (!field) return;
  const pooled = form.elements.namedItem('item').value === 'cords';
  field.hidden = !pooled;
  field.querySelector('input').disabled = !pooled;
}

function conflictError(result, item, quantity) {
  const { free, peak } = result;
  return {
    html: `<strong>${itemLabel(item)} · ${quantity} requested, ${free} available on ${date(peak.day)}.</strong>
      <ul>${peak.blockers.map(span => `<li>${spanText(span)}</li>`).join('')}</ul>`,
  };
}

function recordChange(fresh, data, action) {
  const day = localDay();
  const { mode, id } = action;
  if (mode === 'return') {
    const loan = fresh.loans.find(entry => entry.id === id && remaining(entry) > 0);
    if (!loan) throw new Error('This loan has already been returned.');
    const quantity = Number(data.get('quantity') || 1);
    if (!Number.isInteger(quantity) || quantity < 1 || quantity > remaining(loan)) {
      throw new Error(`Enter a quantity from 1 to ${remaining(loan)}.`);
    }
    loan.returned += quantity;
    return remaining(loan) ? `Return saved. ${remaining(loan)} still out.` : 'Return saved. Loan closed.';
  }

  const booking = fresh.reservations.find(entry => entry.id === id);
  if (mode === 'cancel-booking') {
    if (!booking) throw new Error('This reservation is no longer on the schedule.');
    fresh.reservations = fresh.reservations.filter(entry => entry.id !== id);
    return 'Reservation canceled.';
  }
  const pickup = mode === 'pickup';
  const reserve = mode === 'reserve';
  if (pickup && (!booking || day < booking.start || day > booking.end)) {
    throw new Error('Pickup is available during the reservation dates.');
  }

  const item = pickup ? booking.item : data.get('item');
  const household = pickup ? booking.household : data.get('household').trim();
  const start = pickup ? day : data.get('start');
  const end = pickup ? booking.end : data.get('end');
  const quantity = pickup ? booking.quantity : item === 'cords' ? Number(data.get('quantity')) : 1;
  const capacity = items.find(entry => entry.id === item)?.capacity;
  if (!household || household.length > 24) throw new Error('Enter a household label of 1 to 24 characters.');
  if (!capacity || !Number.isInteger(quantity) || quantity < 1 || quantity > capacity) {
    throw new Error('Choose an item and a valid quantity.');
  }
  if (!start || !end || end < start) throw new Error('Choose an end date on or after the start date.');
  if (reserve && start <= day) throw new Error('Choose a reservation start date after today.');
  if (!reserve && start > day) throw new Error('Choose a checkout date of today or earlier.');

  const result = availability(fresh, item, reserve ? start : day, end < day ? null : end, day, pickup ? id : undefined);
  if (quantity > result.free) throw conflictError(result, item, quantity);

  const entry = { id: crypto.randomUUID(), item, household, quantity, start, end };
  if (reserve) {
    fresh.reservations.push(entry);
    return 'Reservation saved.';
  }
  fresh.loans.push({ ...entry, returned: 0 });
  if (pickup) fresh.reservations = fresh.reservations.filter(entry => entry.id !== id);
  return 'Checkout saved.';
}

form.addEventListener('submit', async event => {
  event.preventDefault();
  const submit = form.querySelector('[type="submit"]');
  const errorBox = form.querySelector('#form-error');
  const data = new FormData(form);
  const action = editing;
  submit.disabled = true;
  try {
    const save = () => {
      const fresh = load();
      const result = recordChange(fresh, data, action);
      localStorage.setItem(key, JSON.stringify(fresh));
      state = fresh;
      return result;
    };
    const result = navigator.locks ? await navigator.locks.request(key, save) : save();
    dialog.close();
    render();
    if (document.activeElement === document.body) document.querySelector('#main').focus({ preventScroll: true });
    showToast(result);
  } catch (error) {
    if (error.html) errorBox.innerHTML = error.html;
    else errorBox.textContent = ['QuotaExceededError', 'SecurityError'].includes(error.name)
      ? 'Could not save in this browser. Check that local storage is allowed and try again.'
      : error.message || 'Could not save the change.';
    errorBox.hidden = false;
    errorBox.focus();
  } finally {
    submit.disabled = false;
  }
});

document.addEventListener('change', event => {
  const target = event.target;
  if (target.form === form && target.name === 'item') syncQuantity();
  if ((target.form === form || target.form?.id === 'range-form') && target.name === 'start') {
    const end = target.form.elements.end;
    end.min = target.value;
    if (end.value < target.value) end.value = target.value;
  }
});

view.addEventListener('submit', event => {
  if (event.target.id !== 'range-form') return;
  event.preventDefault();
  const data = new FormData(event.target);
  range = { start: data.get('start'), end: data.get('end') };
  const results = document.querySelector('#range-results');
  results.innerHTML = availabilityResults();
  paintArt(results);
});

document.addEventListener('click', event => {
  const target = event.target.closest('[data-action]');
  if (!target) return;
  const { action, id, item } = target.dataset;
  if (action === 'close-dialog') { dialog.close(); return; }
  if (action === 'print') { window.print(); return; }
  refreshState();
  if (!state) { render(); return; }
  if (action === 'checkout' || action === 'reserve') openEditor(action);
  if (action === 'reserve-range') {
    if (range.start > localDay()) openEditor('reserve', null, item);
    else { render(); showToast('Choose a start date after today.'); }
  }
  if (action === 'return' || action === 'pickup' || action === 'cancel-booking') {
    const record = action === 'return'
      ? state.loans.find(entry => entry.id === id && remaining(entry) > 0)
      : state.reservations.find(entry => entry.id === id);
    if (record) openEditor(action, record);
    else { render(); showToast('The ledger has changed.'); }
  }
});

window.addEventListener('hashchange', render);
window.addEventListener('storage', event => {
  if (event.key === key || event.key === null) { refreshState(); render(); }
});
window.addEventListener('focus', () => {
  if (!dialog.open && localDay() !== today) { refreshState(); render(); }
});
window.addEventListener('beforeprint', () => {
  today = localDay();
  refreshState();
  renderPrint();
});
setInterval(() => {
  if (!dialog.open && localDay() !== today) { refreshState(); render(); }
}, 30000);

refreshState();
render();

'use strict';

const icons = {
  cupboard: 'M3 3h18v16H3z M12 3v16 M3 19v2m18-2v2 M9 10v3m6-3v3',
  grid: 'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  loan: 'M4 9h16v12H4z M3 4h18v5H3z M9 13h6',
  calendar: 'M4 6h16v15H4z M8 3v6m8-6v6 M4 11h16 M8 15h2m4 0h2m-8 3h2',
  search: 'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0zm-2 5 6 6',
  print: 'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 14h12v7H6z M7 11h1',
  plus: 'M12 5v14M5 12h14',
  close: 'M6 6l12 12M18 6 6 18',
  arrow: 'M4 12h15m-6-6 6 6-6 6',
};

function paintArt(root) {
  for (const canvas of root.querySelectorAll('canvas[data-icon], canvas[data-art]')) {
    const context = canvas.getContext('2d');
    const { width, height } = canvas;
    const ratio = Math.min(window.devicePixelRatio || 1, 3);
    if (canvas.dataset.painted && canvas.dataset.painted === getComputedStyle(canvas).color) continue;
    canvas.width = Math.round((canvas.dataset.width || width) * ratio);
    canvas.height = Math.round((canvas.dataset.height || height) * ratio);
    canvas.dataset.width ||= width;
    canvas.dataset.height ||= height;
    canvas.dataset.painted = getComputedStyle(canvas).color;
    context.scale(ratio, ratio);
    context.strokeStyle = canvas.dataset.painted;
    context.fillStyle = context.strokeStyle;
    context.lineCap = 'round';
    context.lineJoin = 'round';
    if (canvas.dataset.icon) {
      const size = Number(canvas.dataset.width);
      context.scale(size / 24, size / 24);
      context.lineWidth = 1.65;
      context.stroke(new Path2D(icons[canvas.dataset.icon]));
      continue;
    }
    const type = canvas.dataset.art;
    if (type === 'shelf') {
      context.lineWidth = 1.4;
      context.stroke(new Path2D('M78 199H340 M111 191V36h151v155 M107 36h159v-9H107z M111 111h151 M111 184h151 M123 184v16m126-16v16 M124 170h125 M280 196l30-36m-16 36 29-36m-43 36h41m-11-36h22m-30 17h24 M95 202v-54m0 26c-28 1-35-12-34-24 19 0 32 12 34 24zm0-11c1-20 14-31 27-32-1 15-10 26-27 32z M89 192h12l-2 10H91z'));
      context.save();
      context.translate(135, 59);
      context.scale(.9, .9);
      gear(context, 'projector');
      context.restore();
      context.save();
      context.translate(135, 130);
      context.scale(.82, .82);
      gear(context, 'cords');
      context.restore();
      context.save();
      context.translate(197, 129);
      context.scale(.9, .9);
      gear(context, 'table');
      context.restore();
    } else {
      context.lineWidth = 1.65;
      gear(context, type);
    }
  }
}

function gear(context, type) {
  const paths = {
    table: 'M8 20h45l7 9H3z M4 29v4h55v-4 M15 33l-6 15m38-15 6 15 M19 33l-3 8h30m-3-8 3 8 M9 48h5m34 0h5 M12 24h36',
    projector: 'M8 19h45a5 5 0 0 1 5 5v14a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5V24a5 5 0 0 1 5-5z M11 43v4m39-4v4 M15 24a7 7 0 1 1 0 14 7 7 0 0 1 0-14zm0 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8z M30 27h18m-18 5h18m-18 5h11',
    cords: 'M45 41c-4 6-13 8-22 6C9 45 4 34 7 24c3-10 13-14 23-12 12 2 17 11 15 20-2 8-10 11-19 10-8-1-13-6-12-13 1-7 8-11 15-10 7 1 11 6 10 11s-6 8-12 7c-4-1-7-4-6-8 1-3 4-5 8-4 3 0 5 3 3 6 M45 41l5-5 M50 36l-3-4 8-6 5 6-8 6z M56 27l4-4m-1 8 4-3',
  };
  context.stroke(new Path2D(paths[type]));
}

'use strict';

const Ledger = (() => {
  const items = [
    { id: 'T-01', name: 'Folding table', capacity: 1, art: 'table' },
    { id: 'T-02', name: 'Folding table', capacity: 1, art: 'table' },
    { id: 'P-01', name: 'Projector', capacity: 1, art: 'projector' },
    { id: 'cords', name: 'Extension cords', capacity: 3, art: 'cords' },
  ];

  function localDay(date = new Date()) {
    return [
      String(date.getFullYear()).padStart(4, '0'),
      String(date.getMonth() + 1).padStart(2, '0'),
      String(date.getDate()).padStart(2, '0'),
    ].join('-');
  }

  function addDays(day, days) {
    const date = new Date(day + 'T12:00:00');
    date.setDate(date.getDate() + days);
    return localDay(date);
  }

  function remaining(loan) {
    return loan.quantity - loan.returned;
  }

  function commitments(state, item, today, excludeId) {
    const loans = state.loans.filter(loan => loan.item === item && remaining(loan) > 0);
    const bookings = state.reservations.filter(booking =>
      booking.item === item && booking.id !== excludeId && booking.end >= today);
    return [
      ...loans.map(loan => ({
        kind: 'loan', household: loan.household, quantity: remaining(loan),
        start: today, end: loan.end < today ? null : loan.end, due: loan.end,
      })),
      ...bookings.map(booking => ({
        kind: 'reservation', household: booking.household, quantity: booking.quantity,
        start: booking.start, end: booking.end,
      })),
    ];
  }

  // Usage can only increase when a commitment starts. Check those dates
  // and the first requested day to find the tightest point in the range.
  function availability(state, item, start, end, today, excludeId) {
    const capacity = items.find(entry => entry.id === item).capacity;
    const spans = commitments(state, item, today, excludeId).filter(span =>
      (end === null || span.start <= end) && (span.end === null || span.end >= start));
    const checkpoints = [...new Set([start, ...spans.map(span => span.start)
      .filter(day => day > start)])].sort();
    let peak = { day: start, used: 0, blockers: [] };
    for (const day of checkpoints) {
      const active = spans.filter(span => span.start <= day && (span.end === null || span.end >= day));
      const used = active.reduce((total, span) => total + span.quantity, 0);
      if (used > peak.used) peak = { day, used, blockers: active };
    }
    return { free: Math.max(0, capacity - peak.used), peak, spans };
  }

  return { items, localDay, addDays, remaining, availability };
})();

if (typeof module !== 'undefined') module.exports = Ledger;

:root {
  --paper: #f7f6f1;
  --white: #fffefa;
  --sidebar: #edf0e8;
  --ink: #222b23;
  --muted: #596356;
  --line: #dce1d6;
  --green: #223c31;
  --green-dark: #192e26;
  --light-green: #dce9dc;
  --orange: #f0bb91;
  --orange-hover: #f7cba8;
  --focus: #516cbe;
  color: var(--ink);
  background: var(--paper);
  font: 16px/1.5 system-ui, sans-serif;
  color-scheme: light;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin: 0; }
h1, h2, h3, p { margin: 0; }
h1, h2, h3 { line-height: 1.18; }
h1, h2 { letter-spacing: -.035em; }
a { color: inherit; }
button, input, select { font: inherit; }
button, select { cursor: pointer; }
button:disabled { opacity: .55; cursor: wait; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
.skip { position: fixed; z-index: 3; top: 8px; left: 8px; padding: 12px; background: var(--white); transform: translateY(-150%); }
.skip:focus { transform: none; }
.icon { display: inline-block; width: 20px; height: 20px; flex: none; vertical-align: middle; }
.shell { display: grid; grid-template-columns: 227px minmax(0, 1fr); min-height: 100vh; }
.sidebar {
  display: flex; flex-direction: column; gap: 40px;
  background: var(--sidebar); border-right: 1px solid var(--line);
  padding: 30px 17px 24px; position: sticky; top: 0; height: 100vh;
}
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; font-weight: 750; line-height: 1.2; padding: 0 3px; white-space: nowrap; letter-spacing: -.03em; }
.brand canvas { width: 39px; height: 39px; padding: 8px; border-radius: 10px; background: var(--green); color: #eef4eb; }
.brand small { display: block; color: var(--muted); font-size: .72rem; margin-top: 5px; font-weight: 550; letter-spacing: 0; }
nav { display: grid; gap: 6px; }
nav a { text-decoration: none; color: #435244; display: flex; align-items: center; gap: 11px; padding: 11px 12px; min-height: 45px; border-radius: 8px; font-size: .9rem; font-weight: 600; }
nav a:hover { background: #e2e8dd; }
nav [aria-current="page"] { background: #dce7d9; color: #244431; font-weight: 750; }
nav canvas { width: 20px; height: 20px; flex: none; }
.sidebar-foot { color: var(--muted); display: flex; gap: 10px; margin-top: auto; padding: 18px 3px 0; border-top: 1px solid #d2dacd; font-size: .75rem; line-height: 1.5; }
.sidebar-foot strong { font-size: .8rem; color: var(--ink); }
.offline-dot { display: inline-block; flex: none; width: 8px; height: 8px; margin-top: 6px; border-radius: 50%; background: #4a7853; box-shadow: 0 0 0 3px #d8e6d5; }
main { width: 100%; max-width: 1440px; margin-inline: auto; padding: 0 clamp(24px, 3.5vw, 56px) 40px; }
main:focus { outline: none; }
.topbar { min-height: 70px; display: flex; align-items: center; justify-content: space-between; gap: 12px; font-weight: 700; font-size: .92rem; }
.today { color: var(--muted); font-weight: 550; display: flex; gap: 8px; align-items: center; }
.today .icon { width: 17px; height: 17px; }
.hero { position: relative; overflow: hidden; border-radius: 16px; background: var(--green); color: #fffdf5; min-height: 236px; display: grid; align-items: center; padding: 30px 34px; isolation: isolate; }
.hero-copy { position: relative; z-index: 1; }
.hero h1 { font-family: Georgia, serif; font-weight: 500; letter-spacing: -.055em; font-size: clamp(2.6rem, 4.3vw, 4.25rem); }
.hero p { color: #d8e4d9; font-size: .98rem; margin-top: 10px; max-width: 37ch; }
.hero .actions { margin-top: 23px; }
.hero-art { position: absolute; inset: 0 0 0 auto; width: min(43%, 425px); display: grid; place-items: center; color: #bed0a9; background: radial-gradient(circle, #b5c9a546 1px, transparent 1.5px) 0 0 / 16px 16px; mask-image: linear-gradient(to right, transparent 0%, black 21%); }
.hero-art canvas { width: min(100%, 364px); height: auto; }
.actions { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border: 1px solid #cbd3c7; background: var(--white); color: var(--ink); border-radius: 8px; min-height: 44px; padding: 9px 14px; font-size: .88rem; font-weight: 700; text-decoration: none; text-align: center; }
.button:hover { background: #f1f4ec; border-color: #a9b6a7; }
.button.primary { background: var(--orange); border-color: transparent; color: #34251c; }
.button.primary:hover { background: var(--orange-hover); }
.button.on-dark { background: transparent; color: #f0f5eb; border-color: #809287; }
.button.on-dark:hover { background: #334e41; }
.button.dark { background: var(--green); color: white; border-color: var(--green); }
.button.dark:hover { background: var(--green-dark); }
.button.compact { padding: 7px 11px; font-size: .81rem; }
.button.compact .icon { width: 17px; height: 17px; }
.inventory { margin-top: 30px; }
.section-head, .panel-head, .page-heading { display: flex; justify-content: space-between; align-items: center; gap: 14px; }
.section-head { margin-bottom: 15px; }
.section-head h2, .panel h2 { font-size: 1.30rem; }
.section-head p, .page-heading p { color: var(--muted); font-size: .9rem; margin-top: 4px; }
.text-link { display: inline-flex; align-items: center; gap: 4px; min-height: 44px; color: #33583d; font-size: .86rem; font-weight: 750; text-decoration: none; }
.text-link:hover { text-decoration: underline; }
.text-link .icon { width: 17px; height: 17px; }
.inventory-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }
.inventory-card, .panel { background: var(--white); border: 1px solid var(--line); border-radius: 12px; }
.inventory-card { padding: 13px; }
.inventory-art { display: grid; place-items: center; border-radius: 7px; height: 76px; background: #e9eee4; color: #45604b; }
.inventory-art canvas { width: 64px; height: 60px; }
.inventory-art.projector { background: #f1e9d9; color: #785d37; }
.inventory-art.cords { background: #e9e9f0; color: #595777; }
.inventory-label { padding: 11px 1px 10px; }
.item-tag { color: var(--muted); font: 700 .72rem/1.3 ui-monospace, monospace; letter-spacing: .065em; text-transform: uppercase; }
.inventory-label h3, .availability-title h3 { font-size: 1rem; margin-top: 3px; }
.badge { display: inline-flex; align-items: center; gap: 6px; max-width: 100%; padding: 4px 9px; border-radius: 999px; font-size: .74rem; font-weight: 700; line-height: 1.3; background: #e9ece8; color: #3e4d44; }
.badge span { width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.badge.good { background: #e5efe1; color: #2d5937; }
.badge.warm { background: #f5ead8; color: #6f491e; }
.badge.alarm { background: #fae4dd; color: #932f22; }
.dashboard-grid { display: grid; grid-template-columns: 1.15fr 1fr; gap: 15px; margin-top: 24px; }
.panel-head { min-height: 64px; padding: 10px 16px; border-bottom: 1px solid var(--line); }
.panel-head h2 { display: flex; align-items: center; gap: 8px; }
.count { display: inline-grid; place-items: center; padding: 3px 7px; min-width: 23px; border-radius: 20px; background: #eef1eb; color: var(--muted); font-size: .74rem; letter-spacing: 0; }
.empty { display: flex; align-items: center; gap: 13px; min-height: 100px; padding: 18px 16px; font-size: .93rem; }
.empty p { color: var(--muted); font-size: .83rem; margin-top: 2px; }
.empty-icon { display: grid; place-items: center; flex: none; width: 43px; height: 43px; border-radius: 9px; background: #eef1ea; color: #55715b; }
.mini-list { list-style: none; padding: 0 16px; margin: 0; }
.mini-list li { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 11px 0; border-bottom: 1px solid var(--line); font-size: .86rem; overflow-wrap: anywhere; }
.mini-list li:last-child { border-bottom: 0; }
.mini-list small { display: block; color: var(--muted); margin-top: 3px; }
.panel-link { margin-inline: 16px; }
.page-heading { margin: 18px 0 24px; flex-wrap: wrap; }
.page-heading h1 { font-family: Georgia, serif; font-size: clamp(2.3rem, 4vw, 3.4rem); font-weight: 500; }
.table-panel { overflow: hidden; }
table { width: 100%; border-collapse: collapse; text-align: left; font-size: .86rem; }
th, td { padding: 12px; overflow-wrap: anywhere; }
th { background: #eef1ea; font-size: .77rem; color: #49584a; }
tbody tr + tr { border-top: 1px solid var(--line); }
td small { color: var(--muted); }
.row-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.range-form { padding: 20px; display: grid; grid-template-columns: repeat(2, minmax(0, 220px)) auto; align-items: end; justify-content: start; gap: 12px; }
.range-form p { grid-column: 1/-1; color: var(--muted); font-size: .84rem; }
.range-results { margin-top: 24px; }
.availability-list { display: grid; gap: 10px; }
.availability-item { padding: 12px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.availability-title { display: flex; align-items: center; gap: 13px; margin-right: auto; }
.availability-title .inventory-art { width: 60px; height: 53px; }
.availability-title canvas { width: 48px; height: 45px; }
details { flex-basis: 100%; border-top: 1px solid var(--line); font-size: .86rem; color: var(--muted); }
summary { display: list-item; min-height: 44px; padding: 10px 1px; cursor: pointer; font-weight: 650; color: var(--ink); }
details ul { margin-top: 0; padding-left: 24px; overflow-wrap: anywhere; }
label { display: grid; gap: 5px; color: var(--ink); font-size: .88rem; font-weight: 650; min-width: 0; }
input, select { width: 100%; min-width: 0; min-height: 44px; border: 1px solid #aebbae; background: #fff; color: var(--ink); border-radius: 7px; padding: 8px 9px; font-size: 1rem; }
dialog { width: min(500px, calc(100% - 24px)); max-height: calc(100% - 24px); padding: 0; border: 1px solid var(--line); border-radius: 15px; background: var(--white); color: var(--ink); box-shadow: 0 16px 70px #18261a45; }
dialog::backdrop { background: #18251ccc; }
#record-form { padding: 22px; }
.dialog-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.dialog-head h2 { font-size: 1.55rem; }
.dialog-message { color: var(--muted); font-size: .88rem; margin-top: 5px; overflow-wrap: anywhere; }
.icon-button { min-width: 44px; min-height: 44px; border: 0; border-radius: 7px; background: transparent; color: var(--ink); }
.icon-button:hover { background: #eef1ea; }
.fields { display: grid; gap: 13px; margin-top: 16px; }
.fields:empty { display: none; }
.field-row { display: flex; gap: 11px; }
.field-row label { flex: 1; }
.dialog-actions { margin-top: 21px; display: flex; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
.error { margin-top: 13px; border: 1px solid #e9ae9c; border-radius: 8px; background: #fdf0ea; color: #742d23; font-size: .875rem; padding: 10px 13px; overflow-wrap: anywhere; }
.error ul { margin: 5px 0 0; padding-left: 20px; }
#toast:not(:empty) { position: fixed; z-index: 2; right: 18px; bottom: 18px; max-width: calc(100% - 36px); padding: 12px 16px; border-radius: 8px; background: var(--green); color: white; font-size: .9rem; box-shadow: 0 6px 18px #1b2f2835; }
#print-sheet { display: none; }

@media (max-width: 1060px) {
  .shell { grid-template-columns: 197px minmax(0, 1fr); }
  .sidebar { padding-inline: 11px; }
  .hero-art { width: 38%; }
  .table-panel table, .table-panel tbody, .table-panel tr, .table-panel td { display: block; }
  .table-panel thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  .table-panel tr { padding: 13px; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 16px; }
  .table-panel td { padding: 0; }
  .table-panel td::before { content: attr(data-label); display: block; font-weight: 750; font-size: .73rem; color: var(--muted); }
}

@media (max-width: 800px) {
  .shell { display: block; }
  .sidebar { position: static; height: auto; gap: 12px; padding: 12px 18px 8px; border-right: 0; border-bottom: 1px solid var(--line); }
  .sidebar-foot { display: none; }
  nav { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  nav a { justify-content: center; padding: 8px 3px; gap: 5px; font-size: .8rem; }
  nav canvas { width: 17px; height: 17px; }
  main { padding-inline: 18px; }
  .topbar { min-height: 58px; }
}

@media (max-width: 560px) {
  .hero { min-height: auto; padding: 24px 19px; }
  .hero-art { display: none; }
  .inventory-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
  .dashboard-grid { grid-template-columns: 1fr; }
  .inventory-card { padding: 9px; }
  .range-form { grid-template-columns: repeat(2, minmax(0, 1fr)); padding: 12px; }
  .range-form button { grid-column: 1 / -1; justify-self: start; }
  .availability-item { gap: 8px; }
  .section-head { gap: 8px; align-items: flex-start; }
  .section-head .text-link { max-width: 110px; text-align: right; }
  .sidebar { padding-inline: 10px; }
  nav a { flex-direction: column; line-height: 1.2; text-align: center; min-height: 49px; }
  .topbar { font-size: .82rem; }
  #record-form { padding: 15px; }
}

@media (max-width: 360px) {
  nav { gap: 4px; }
  nav a { font-size: .72rem; }
}

@media print {
  @page { margin: 14mm; }
  body { background: white; color: black; }
  .shell, .skip, #toast, dialog { display: none !important; }
  #print-sheet { display: block; font: 11pt/1.35 system-ui, sans-serif; }
  #print-sheet h1 { font-size: 21pt; margin-bottom: 4pt; }
  #print-sheet table { margin-top: 18pt; font-size: 10pt; }
  #print-sheet th, #print-sheet td { border-bottom: 1px solid #b7b7b7; color: black; background: white; padding: 6pt 4pt; }
  #print-sheet thead { display: table-header-group; }
  #print-sheet tr { break-inside: avoid; }
}
